	@Test
	public void projectionFreeMatricesUsePrimitivePlaneMorselTypeAccess() throws Exception {
		Expected expected = openRepository(4000, true);
		AtomicLong planeMorselRuns = metric("PLANE_MORSEL_RUNS");
		AtomicLong sourceTypeBatchLookups = metric("SOURCE_TYPE_BATCH_LOOKUPS");
		AtomicLong targetTypeBatchLookups = metric("TARGET_TYPE_BATCH_LOOKUPS");
		AtomicLong edgeFibersVisited = metric("EDGE_FIBERS_VISITED");
		AtomicLong uniqueTargetsResolved = metric("UNIQUE_TARGETS_RESOLVED");
		AtomicLong targetTypeRunsDecoded = metric("TARGET_TYPE_RUNS_DECODED");
		AtomicLong labelSynopsisSlices = metric("LABEL_SYNOPSIS_SLICES");
		AtomicLong nonResourcePlanesPruned = metric("NON_RESOURCE_PLANES_PRUNED");
		long runsBefore = planeMorselRuns.get();
		long sourceBefore = sourceTypeBatchLookups.get();
		long targetBefore = targetTypeBatchLookups.get();
		long fibersBefore = edgeFibersVisited.get();
		long uniqueBefore = uniqueTargetsResolved.get();
		long decodedBefore = targetTypeRunsDecoded.get();
		long synopsisBefore = labelSynopsisSlices.get();
		long nonResourcePlanesBefore = nonResourcePlanesPruned.get();

		assertThat(matrix(USAGE_MATRIX, "type", "p", "statements")).isEqualTo(expected.usage);
		assertThat(matrix(LINKAGE_MATRIX, "sourceType", "targetType", "links")).isEqualTo(expected.linkage);
		assertThat(planeMorselRuns.get()).isGreaterThan(runsBefore + 1L);
		boolean decodedBatchPath = sourceTypeBatchLookups.get() > sourceBefore
				&& targetTypeBatchLookups.get() > targetBefore;
		boolean synopsisPath = labelSynopsisSlices.get() > synopsisBefore;
		assertThat(decodedBatchPath || synopsisPath)
				.as("type access must use either batched run lookup or the exact compact label synopsis")
				.isTrue();
		long fibers = edgeFibersVisited.get() - fibersBefore;
		long uniqueTargets = uniqueTargetsResolved.get() - uniqueBefore;
		long decodedTargets = targetTypeRunsDecoded.get() - decodedBefore;
		assertThat(fibers).isGreaterThan(uniqueTargets);
		assertThat(decodedTargets).isLessThanOrEqualTo(uniqueTargets);
		assertThat(nonResourcePlanesPruned.get())
				.as("linkage must prune the literal-only name plane from CSF page traits")
				.isGreaterThan(nonResourcePlanesBefore);
	}

